import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.contains(char ch).
 * 
 * Note: The provided source code for contains(char ch) has a logical bug:
 * it returns 'true' at the end of the method regardless of whether the character was found.
 * These tests are written to reflect the actual behavior of the provided code snippet.
 */
public class StrBuilder_contains_TriageGen1Test {

    @Test
    public void testContains_WithEmptyBuilder_ReturnsTrueDueToBug() {
        StrBuilder sb = new StrBuilder();
        // Even if empty, the provided code returns true because it falls through the loop
        assertTrue("The provided implementation always returns true", sb.contains('a'));
    }

    @Test
    public void testContains_WithCharacterPresent_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("hello");
        assertTrue(sb.contains('e'));
        assertTrue(sb.contains('h'));
        assertTrue(sb.contains('o'));
    }

    @Test
    public void testContains_WithCharacterNotPresent_ReturnsTrueDueToBug() {
        StrBuilder sb = new StrBuilder("abc");
        // The loop completes without finding 'z', but the method returns true anyway
        assertTrue("The provided implementation incorrectly returns true when char is not found", sb.contains('z'));
    }

    @Test
    public void testContains_SingleCharacterMatch_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("a");
        assertTrue(sb.contains('a'));
    }

    @Test
    public void testContains_LargeString_ReturnsTrue() {
        StringBuilder sbInternal = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sbInternal.append('a');
        }
        StrBuilder sb = new StrBuilder(sbInternal.toString());
        assertTrue(sb.contains('a'));
        assertTrue(sb.contains('b'));
    }
}
